// Blog data layer. Pages read posts only through listPosts()/getPost(), so this
// is the one seam to swap for a database + object storage (with an authenticated
// editor writing the same Block format) later. Today it reads content/blog/*.json,
// generated by scripts/convert-blog.mjs.
import fs from "node:fs/promises";
import path from "node:path";
import { safeEmbedSrc, sanitizeInlineHtml } from "./sanitize-html.mjs";

// Image src is an asset path (render with asset()). Paragraph html is limited to
// inline tags (see sanitize-html.mjs) and embeds to YouTube; getPost enforces both.
export type Block =
  | { type: "paragraph"; html: string }
  | { type: "image"; src: string }
  | { type: "code"; text: string }
  | { type: "embed"; src: string };

export type Post = {
  id: string;
  title: string;
  author: string;
  date: string; // ISO 8601, UTC
  cover: string; // asset path
  blocks: Block[];
};

export type PostSummary = Omit<Post, "blocks"> & { excerpt: string };

const dir = path.join(process.cwd(), "content/blog");

async function readPost(file: string): Promise<Post> {
  return JSON.parse(await fs.readFile(path.join(dir, file), "utf8"));
}

function excerpt(blocks: Block[], max = 160) {
  const first = blocks.find((b) => b.type === "paragraph");
  if (!first) return "";
  const text = first.html
    .replace(/<[^>]*>/g, "")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, "&");
  if (text.length <= max) return text;
  return text.slice(0, text.lastIndexOf(" ", max)).replace(/[\s,.;:]+$/, "") + "…";
}

export async function listPosts(): Promise<PostSummary[]> {
  const files = (await fs.readdir(dir)).filter((f) => f.endsWith(".json"));
  const posts = await Promise.all(files.map(readPost));
  return posts
    .sort((a, b) => b.date.localeCompare(a.date))
    .map(({ blocks, ...meta }) => ({ ...meta, excerpt: excerpt(blocks) }));
}

// Re-sanitises on read so the renderer never trusts stored HTML or embed URLs.
function sanitize(blocks: Block[]): Block[] {
  return blocks.flatMap((b): Block[] => {
    if (b.type === "paragraph") return [{ type: "paragraph", html: sanitizeInlineHtml(b.html) }];
    if (b.type === "embed") {
      const src = safeEmbedSrc(b.src);
      return src ? [{ type: "embed", src }] : [];
    }
    return [b];
  });
}

export async function getPost(id: string): Promise<Post | null> {
  if (!/^\d{6}$/.test(id)) return null;
  let post: Post;
  try {
    post = await readPost(`${id}.json`);
  } catch {
    return null;
  }
  return { ...post, blocks: sanitize(post.blocks) };
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

// Formatted in UTC by hand so server output never depends on locale or timezone.
export function formatDate(iso: string) {
  const d = new Date(iso);
  return `${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}, ${d.getUTCFullYear()}`;
}
